"""Exam format config loader (독립된 설정 데이터: data/exam_formats.json, generated by make_formats.py).

Each grade lists *slots*: one per official question type (한국어문회) or per app-defined multiple-choice
type (대한검정회, whose per-type mix is not published). A slot has the app question ``type`` that fills it,
the official type key it stands for (``official``), its count and points. When the official type needs
data the app does not have yet (e.g. 讀音 needs 한자어 vocabulary), the slot is filled by the closest
supported type and the grade records that in ``substitutions`` with ``type_mix: "partial_substitution"``.
"""
from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Optional, Tuple

DATA = Path(__file__).resolve().parents[2] / "data"
TYPES = ("eum", "hun_eum", "hun_to_hanja", "writing", "busu", "pilsun")
CHOICE_TYPES = ("eum", "hun_eum", "hun_to_hanja", "busu", "pilsun")
TYPE_MIXES = ("official", "partial_substitution", "app_defined")

# Labels for app-defined slots (대한검정회). 한국어문회 slots carry the official type label.
APP_TYPE_LABELS = {"eum": "음(소리) 고르기", "hun_eum": "훈음 고르기", "hun_to_hanja": "한자 고르기",
                   "writing": "한자 쓰기", "busu": "부수", "pilsun": "필순"}
SUBSTITUTION_NOTICE = "일부 유형은 준비 중이라 비슷한 유형으로 대체됐어요"


class FormatError(Exception):
    pass


@dataclass(frozen=True)
class TypeSpec:
    type: str           # app question type that generates the questions
    count: int
    points: int
    slot: str = ""      # official type key (한국어문회) or the app type (대한검정회); result key
    label: str = ""     # shown on the result screen (official name for 한국어문회)
    substituted: bool = False  # the official type is not built yet; `type` stands in for it

    @property
    def key(self) -> str:
        return self.slot or self.type


@dataclass(frozen=True)
class ExamFormat:
    body: str
    grade: str
    minutes: int
    pass_score: int                      # points
    types: Tuple[TypeSpec, ...]
    verified: Dict[str, bool] = field(default_factory=dict)  # per value: total/pass/minutes/type_counts/...
    type_mix: str = "official"
    pass_questions: Optional[int] = None  # official pass line in questions (e.g. 대한검정회 18/25, 35/50)
    notice: Optional[str] = None          # parent/result notice (substitution)
    substitutions: Dict[str, dict] = field(default_factory=dict)

    @property
    def question_count(self) -> int:
        return sum(t.count for t in self.types)

    @property
    def total_score(self) -> int:
        return sum(t.count * t.points for t in self.types)

    @property
    def points_per_question(self) -> Optional[int]:
        pts = {t.points for t in self.types}
        return pts.pop() if len(pts) == 1 else None

    @property
    def has_writing(self) -> bool:
        return any(t.type == "writing" and t.count > 0 for t in self.types)

    @property
    def all_choice(self) -> bool:
        return all(t.type in CHOICE_TYPES for t in self.types)


FORMAT_PENDING_MESSAGE = "형식 준비 중"


def load_pending(path: Path = DATA / "exam_formats.json") -> Dict[Tuple[str, str], str]:
    """(body, grade) -> reason, for supported grades whose official exam format is not known yet.

    Kept for future grades without a published format; every currently supported grade has one."""
    raw = json.loads(path.read_text(encoding="utf-8")).get("format_pending") or {}
    return {(body, g): str(reason) for body, grades in raw.items() for g, reason in grades.items()}


def exam_status(formats: Dict[Tuple[str, str], "ExamFormat"], pending: Dict[Tuple[str, str], str],
                body: str, grade: str) -> str:
    """'available' | 'format_pending' | 'unsupported'."""
    if (body, grade) in formats:
        return "available"
    if (body, grade) in pending:
        return "format_pending"
    return "unsupported"


def _spec(t: dict) -> TypeSpec:
    return TypeSpec(t["type"], int(t["count"]), int(t["points"]), t.get("official") or t["type"],
                    t.get("label") or APP_TYPE_LABELS.get(t["type"], t["type"]), bool(t.get("substituted", False)))


def load_formats(path: Path = DATA / "exam_formats.json") -> Dict[Tuple[str, str], ExamFormat]:
    raw = json.loads(path.read_text(encoding="utf-8"))["bodies"]
    out: Dict[Tuple[str, str], ExamFormat] = {}
    for body, grades in raw.items():
        for grade, v in grades.items():
            specs = tuple(_spec(t) for t in v["types"])
            for s in specs:
                if s.type not in TYPES:
                    raise FormatError(f"{body}/{grade}: unknown type {s.type}")
            ver = v.get("verified", {})
            mix = v.get("type_mix", "official")
            if mix not in TYPE_MIXES:
                raise FormatError(f"{body}/{grade}: unknown type_mix {mix}")
            f = ExamFormat(body, grade, int(v["minutes"]), int(v["pass_score"]), specs,
                           dict(ver) if isinstance(ver, dict) else {"all": bool(ver)}, mix,
                           v.get("pass_questions"), v.get("notice"), dict(v.get("substitutions") or {}))
            if not 0 < f.pass_score <= f.total_score:
                raise FormatError(f"{body}/{grade}: pass_score outside 1..{f.total_score}")
            if "total" in v and int(v["total"]) != f.question_count:
                raise FormatError(f"{body}/{grade}: slots sum to {f.question_count}, total is {v['total']}")
            if len({s.key for s in specs}) != len(specs):
                raise FormatError(f"{body}/{grade}: duplicate type slot")
            out[(body, grade)] = f
    overlap = set(out) & set(load_pending(path))
    if overlap:
        raise FormatError(f"grades both formatted and format_pending: {sorted(overlap)}")
    return out
